    public function getSourceContext(): Source
    {
        return new Source("{% extends 'login.html.twig' %}

{% block title %}Connexion{% endblock %}
{%block aa%}
{% endblock %}
{%block bb%}
{% endblock %}
{%block cc%}
{% endblock %}
{% block body %}
    <h1>Connexion</h1>

    {% if error %}
        <div class=\"alert alert-danger\">{{ error.messageKey|trans(error.messageData, 'security') }}</div>
    {% endif %}

    <form method=\"post\">
        <div class=\"form-group\">
            <label for=\"username\">Email</label>
            <input type=\"email\" value=\"{{ last_username }}\" name=\"username\" id=\"username\" class=\"form-control\" required autofocus>
        </div>
       
        <div class=\"form-group\">
            <label for=\"password\">Mot de passe</label>
            <input type=\"password\" name=\"password\" id=\"password\" class=\"form-control\" required>
        </div>

        <input type=\"hidden\" name=\"_csrf_token\" value=\"{{ csrf_token('authenticate') }}\">

        <button type=\"submit\" class=\"btn btn-primary\">Se connecter</button>
        <a href=\"{{ path('app_register') }}\" class=\"btn btn-secondary ml-2\">S'inscrire</a>

    </form>
{% endblock %}", "login/index.html.twig", "C:\\Users\\Motaz\\mm Dropbox\\Motaz Sammoud\\PC\\Desktop\\hahaha\\symfony\\templates\\login\\index.html.twig");
